#include <zlib.h>

using namespace std;

vector<unsigned char> compressFile(const string& filename) {
    ifstream in(filename);
    if (!in) {
        cerr << "Error: cannot open file '" << filename << "'" << endl;
        return {};
    }
    string data((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    in.close();

    const unsigned char* src = data.data();
    size_t len = data.size();

    vector<unsigned char> out(len * 2);
    int compressedLen = zlib_deflate(out.data(), out.size(), src, len, out.data(), out.size());
    out.resize(compressedLen);
    return out;
}

// Decompress a vector<unsigned char> to a string (or raw bytes)
string decompressFile(const vector<unsigned char>& compressed) {
    // Estimate decompressed size (usually less than compressed)
    size_t estLen = compressed.size() * 2; // heuristic
    string result(estLen, '\0');

    // Allocate Z_BUFFER and Z_STREAM
    Z_BUFFER* cb = (Z_BUFFER*)new Z_BUFFER(); // dynamic allocation
    Z_STREAM* st = zlib_create_stream(cb, compressed.size());
    Z_BUF_RW* rw = zlib_alloc_buffer(st, compressed.size());
    if (!rw) {
        cerr << "Allocation failed during decompression\n";
        return result;
    }
    memcpy(rw->buf, compressed.data(), compressed.size());
    zlib_set_flags(st, Z_FINISH | Z_UNCOMPRESSED);
    int decodedLen = zlib_inflate(rw->buf, compressed.size(), st);
    zlib_end_stream(st, cb);
    zlib_free(rw);
    delete cb;
    // Trim result to decodedLen
    result.resize(decodedLen);
    return result;
