use tokio::fs as tokio_fs;
use std::path::PathBuf;

#[derive(Debug, Deserialize)]
struct PatchEntry { file_name: String }

#[derive(Debug, Serialize, Clone)]
struct DownloadMessage { message: String }

#[derive(Debug, Serialize, Clone)]
struct DownloadInfo { current_file: usize, total_files: usize,
                       file_name: String, downloaded_bytes: u64, total_bytes: u64 }

fn get_exe_dir() -> PathBuf {
    std::env::current_exe()
        .unwrap()
        .parent()
        .unwrap()
        .to_path_buf()
}

async fn read_patch_file(path: &Path) -> Result<Vec<PatchEntry>, Box<dyn std::error::Error>> {
    let content = tokio_fs::read_to_string(path).await?;
    serde_json::from_str(&content).await? // assume async? Actually serde_json is sync, but we can await if needed.
    Ok(content.parse().unwrap_or_default().into_iter().collect())
}

async fn download_file(
    app_handle: &AppHandle,
    client: &Client,
    entry: PatchEntry,
    download_dir: &Path,
    current_file: usize,
    total_files: usize,
) -> Result<(), Box<dyn std::error::Error>> {
    let url = format!("https://hil-speed.hetzner.com/{}", entry.file_name);
    let file_path = download_dir.join(&entry.file_name);

    let mut response = client.get(&url).send().await?;
    let total_bytes = response.content_length().unwrap_or(0);

    let mut file = tokio_fs::OpenOptions::new()
        .write(true)
        .create(true)
        .open(file_path)
        .await?;

    let mut downloaded_bytes = 0;
    let start_time = Instant::now();

    while let Some(chunk) = response.chunk().await? {
        file.write_all(&chunk).await?;
        downloaded_bytes += chunk.len() as u64;

        // No loop, apenas atualiza contador
    }

    Ok(())
}

// Função principal
#[tauri::command]
pub async fn start_downloads(app_handle: AppHandle) -> Result<(), String> {
    let exe_dir = get_exe_dir();
    let patch_file_path = exe_dir.join("patch.json");
    let download_dir = exe_dir.join("patchs");

    if !download_dir.exists() {
        tokio_fs::create_dir_all(&download_dir).await.map_err(|e| e.to_string())?;
    }

    let patches = read_patch_file(&patch_file_path).await.map_err(|e| e.to_string())?;
    let client = Client::new();
    let total_files = patches.len();

    // Emit apenas no início e na conclusão
    app_handle.emit("download_message", DownloadMessage { message: "Conectando ao servidor...".to_string() })
        .map_err(|e| e.to_string())?;

    // Criar um canal para enviar mensagens de progresso
    let messages_channel = Channel::new::<DownloadMessage>(); // ou um tipo personalizado

    // Iterar sobre patches
    for (idx, entry) in patches.into_iter().enumerate() {
        let current_file = idx + 1;
        // Executar download em uma tarefa separada (para não bloquear)
        tokio::spawn(async move {
            let result = download_file(&app_handle, &client, entry, &download_dir, current_file, total_files).await;
            match result {
                Ok(_) => {} // OK
                Err(e) => {
                    eprintln!("Erro ao baixar arquivo: {}", e);
                    // Emit erro apenas uma vez por download
                    app_handle.emit("download_message", DownloadMessage { 
                        message: format!("Erro ao baixar arquivo: {}", e) 
                    }).map_err(|e| e.to_string())?;
                }
            }
        });
    }

    // Após todos os downloads, emit concluído
    app_handle.emit("download_message", DownloadMessage { message: "Download concluído".to_string() })
        .map_err(|e| e.to_string())?;

    // Opcional: fechar o canal após a operação
    Ok(())
}
```

#### Usando um `Channel` para comunicação mais limpa

Se quiser que o frontend receba uma lista de mensagens (ex.: "Baixando", "Download concluído") de forma estruturada, crie um canal:

```rust
let messages_channel = tauri::Channel::new::<DownloadMessage>();
```

E depois, em vez de `app_handle.emit`, faça:

```rust
messages_channel.send(DownloadMessage { message: "Conectando..." })?.await;
...
messages_channel.send(DownloadMessage { message: "Download concluído" })?.await;
```

No frontend, você receberá esses mensagens como eventos em um canal, permitindo que o componente reaja de maneira controlada.

### Resumo das mudanças

- **Remova `emit` dentro do loop** de chunks.
- **Emit apenas nos pontos críticos** (início, fim, erro).
- **Use `tokio::spawn`** para executar cada download em sua própria tarefa, evitando bloqueio.
- **Considere um `Channel`** para transmitir dados estruturados, em vez de disparar múltiplos `emit`s rápidos.

Com essas alterações, o lag deve diminuir e o código ficará mais responsivo.

